import json,urllib.request,datetime,hashlib
base='http://127.0.0.1:17448'
def get(path):
 try:
  with urllib.request.urlopen(base+path,timeout=8) as f:return json.load(f)
 except Exception as e:return {'probe_error':type(e).__name__}
a=get('/api/supervisor-watchdog/agent-assignments')
c=get('/api/supervisor-watchdog/managed-chats')
p=get('/api/projects/control-plane?inspect=0')
ass=a.get('assignments',[]) if isinstance(a.get('assignments'),list) else []
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'assignment_probe_error':a.get('probe_error'),'chat_probe_error':c.get('probe_error'),'total':len(ass),'active_or_pending':[],'recent':[],'chats':[],'control_plane':{'object':p.get('object'),'agent_count':len(p.get('agents',[])) if isinstance(p.get('agents'),list) else None,'conflict_count':len(p.get('conflicts',[])) if isinstance(p.get('conflicts'),list) else None,'counters':p.get('counters')}}
keys=('id','state','targetChatId','dispatchCount','dispatchSubmitAttempted','lastDiagnostic','lastPreflightReason','ciConclusion','createdAt','updatedAt','nextAttemptAt','lastProgressAt','providerMessageId')
for v in ass:
 x={k:v.get(k) for k in keys if k in v}
 if v.get('state') in ('queued','active','running','awaiting_evidence','dispatching','in_progress'):out['active_or_pending'].append(x)
out['recent']=[{k:v.get(k) for k in keys if k in v} for v in ass[-12:]]
for v in c.get('chats',[]) if isinstance(c.get('chats'),list) else []:out['chats'].append({k:v.get(k) for k in ('name','status','error','highMode','generating','openTabs','lastSeenAt','chatId') if k in v})
print(json.dumps(out,ensure_ascii=True,default=str)[:19000])
